    /\ rdn RSEGS m' (Z_to_bv 64 (bv_unsigned pp)) (length str + 1) = Some (str ++ [Z_to_bv 8 0])
    /\ (forall a, shw8 (bv_unsigned pp) <= a < shw8 (bv_unsigned pp + Z.of_nat (length str)) + 8 -> m' (Z_to_bv 64 a) = Some (Z_to_bv 8 0)).
